package com.samsixx.pocket2droid;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import android.graphics.Bitmap;
import java.io.*;import java.util.*;import java.util.concurrent.atomic.*;import org.json.*;
/** Actual settings view and asset/launch boundaries in an owned PC-only test app. */
public final class GlesAutomaticUiTest extends Instrumentation {
 int checks;final AtomicReference<RomSettingsActivity> activity=new AtomicReference<>();
 @Override public void onCreate(Bundle a){super.onCreate(a);start();}
 @Override public void callActivityOnResume(Activity a){super.callActivityOnResume(a);if(a instanceof RomSettingsActivity)activity.set((RomSettingsActivity)a);}
 void yes(boolean b,String why){if(!b)throw new AssertionError(why);checks++;}
 void main(Runnable r){AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{r.run();}catch(Throwable t){error.set(t);}});waitForIdleSync();if(error.get()!=null)throw new AssertionError("Settings view assertion",error.get());}
 View text(View view,String value){if(view instanceof TextView&&value.contentEquals(((TextView)view).getText()))return view;if(view instanceof ViewGroup){ViewGroup g=(ViewGroup)view;for(int i=0;i<g.getChildCount();i++){View v=text(g.getChildAt(i),value);if(v!=null)return v;}}return null;}
 RomSettingsActivity ready()throws Exception{long end=SystemClock.uptimeMillis()+15000;while(SystemClock.uptimeMillis()<end){RomSettingsActivity a=activity.get();AtomicBoolean loaded=new AtomicBoolean();if(a!=null)main(()->loaded.set(text(a.getWindow().getDecorView(),"Delete ROM")!=null));if(loaded.get())return a;Thread.sleep(100);}throw new AssertionError("Settings view did not load");}
 void inspect(RomSettingsActivity a){main(()->{View root=a.getWindow().getDecorView();yes(text(root,"GLES support (experimental)")==null,"GLES support control must be absent");yes(text(root,"GLES renderer")==null,"GLES renderer control must be absent");yes(text(root,"GRAPHICS")==null,"Obsolete graphics section must be absent");yes(text(root,"Guest resolution")!=null&&text(root,"StorageCard folder")!=null&&text(root,"Internet access")!=null,"Other ROM controls must remain");View update=text(root,"Update/Change ROM"),delete=text(root,"Delete ROM");yes(update!=null&&delete!=null&&update.getParent()==delete.getParent()&&((ViewGroup)update.getParent()).indexOfChild(update)<((ViewGroup)delete.getParent()).indexOfChild(delete),"ROM update action must remain above Delete");});}
 static String read(File f)throws Exception{try(FileInputStream in=new FileInputStream(f)){byte[] b=new byte[(int)f.length()];int n=in.read(b);if(n!=b.length)throw new IOException("Short fixture read");return new String(b,"UTF-8");}}
 @Override public void onStart(){Bundle result=new Bundle();try{
  Context c=getTargetContext();yes(c.getPackageName().equals("com.samsixx.p2dautogles"),"Owned PC test package only");StorageLayout paths=StorageLayout.forContext(c);yes(paths.root.getCanonicalPath().startsWith(c.getExternalFilesDir(null).getCanonicalPath()+"/.p2d-rom-update-ui-"),"App-private test files only");
  File card=new File(paths.root.getParentFile(),"card");card.mkdirs();RomRepository repo=new RomRepository(paths.root,paths.runtime,card);RomProfile imported=repo.importRom(new ByteArrayInputStream("fixture ROM".getBytes("UTF-8")),"Fixture.BIN");
  File profileFile=new File(imported.storage.getParentFile(),"profile.json");JSONObject json=new JSONObject(read(profileFile));json.put("glesEnabled",false).put("glesGpuEnabled",false);try(FileOutputStream out=new FileOutputStream(profileFile)){out.write(json.toString().getBytes("UTF-8"));out.getFD().sync();}
  startActivitySync(new Intent(c,RomSettingsActivity.class).putExtra("rom",imported.filename).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));RomSettingsActivity a=ready();inspect(a);
  RomProfile profile=repo.getProfile(imported.filename);yes(profile.settings.glesEnabled&&profile.settings.glesGpuEnabled,"Legacy Off/CPU profile must use automatic GPU");yes(profile.settings.card.equals(card)&&profile.settings.networkMac.equals(imported.settings.networkMac)&&profile.settingsKey.equals(imported.settingsKey),"Storage/network/setup identity must be retained");
  for(RomSettings settings:new RomSettings[]{profile.settings,null}){String key=settings==null?"legacy":profile.settingsKey;GlesSetup.Bundle setup=GlesSetup.prepare(c,key,settings,null);yes(setup!=null&&setup.enabled,"Automatic setup must be provided to all launches");yes(read(new File(setup.directory,"mode.txt")).equals("on gpu"),"Verified guest mode must request GPU preferred");yes(GlesSetup.appendMachineOptions("p2d-devemu",setup,new File(c.getFilesDir(),"libp2d_gles.so")).contains(",gles-renderer="),"Host graphics endpoint must be attached");}
  ProcessBuilder process=new ProcessBuilder("not-started");process.environment().put("P2D_GLES_BACKEND","cpu");Engine.configureGlesBackend(process,profile.settings);yes(process.environment().get("P2D_GLES_BACKEND").equals("gpu"),"Actual ART launch policy must replace inherited CPU selection");
  main(()->a.recreate());Thread.sleep(300);inspect(ready());
  File evidence=new File(c.getFilesDir(),"evidence");evidence.mkdirs();Bitmap shot=getUiAutomation().takeScreenshot();if(shot!=null)try(FileOutputStream out=new FileOutputStream(new File(evidence,"settings-automatic.png"))){shot.compress(Bitmap.CompressFormat.PNG,100,out);}finally{shot.recycle();}
  byte[] rom=new byte[0x50000];java.nio.ByteBuffer b=java.nio.ByteBuffer.wrap(rom).order(java.nio.ByteOrder.LITTLE_ENDIAN);b.position(0x30040);b.put(new byte[]{69,67,69,67}).putInt((int)0x88031000L);b.putInt(0x31030,1);b.position(0x31000+84+12);b.putInt(256).putInt(256).putInt((int)0x88032000L).putInt((int)0x88033000L);byte[] name="libGLES_CM.dll".getBytes("US-ASCII");System.arraycopy(name,0,rom,0x32000,name.length);rom[0x33000]=77;rom[0x33001]=90;b.putInt(0x33000+60,64);b.putInt(0x33000+64,0x00004550);b.putShort(0x33000+68,(short)0x1c0);b.putShort(0x33000+64+22,(short)0x2000);b.putShort(0x33000+64+24,(short)0x10b);b.putShort(0x33000+64+92,(short)9);
  repo.importRom(new ByteArrayInputStream(rom),"Renamed.BIN");repo.importRom(new ByteArrayInputStream("normal".getBytes("UTF-8")),"Contains_GLES_In_Name.BIN");
  MainActivity library=(MainActivity)startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));long deadline=SystemClock.uptimeMillis()+15000;AtomicBoolean loaded=new AtomicBoolean();
  while(SystemClock.uptimeMillis()<deadline){main(()->loaded.set(text(library.getWindow().getDecorView(),"Contains_GLES_In_Name.BIN")!=null));if(loaded.get())break;Thread.sleep(100);}yes(loaded.get(),"Actual library rows must load");
  main(()->{View root=library.getWindow().getDecorView();View supported=text(root,"Renamed.BIN"),normal=text(root,"Contains_GLES_In_Name.BIN");yes(supported!=null&&text((View)supported.getParent(),"GLES")!=null,"GLES ROM must have the approved GLES-only badge below its filename");yes(normal!=null&&text((View)normal.getParent(),"GLES")==null,"Filename-only GLES claim must not create a badge");});
  shot=getUiAutomation().takeScreenshot();if(shot!=null)try(FileOutputStream out=new FileOutputStream(new File(evidence,"library-gles.png"))){shot.compress(Bitmap.CompressFormat.PNG,100,out);}finally{shot.recycle();}
  result.putString("stream","PASS Automatic GLES Android UI: "+checks+" checks\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable error){StringWriter out=new StringWriter();error.printStackTrace(new PrintWriter(out));result.putString("stream",out.toString());finish(Activity.RESULT_CANCELED,result);}}
}
